#!/usr/bin/env python3
from pathlib import Path
import re, sys

if len(sys.argv) != 3:
    raise SystemExit('usage: patch.py COMPONENT_ROOT PLUGIN_ROOT')
comp = Path(sys.argv[1]); plug = Path(sys.argv[2])
builder = comp / 'administrator/components/com_decaroforms/tmpl/builder/default.php'
helper = comp / 'administrator/components/com_decaroforms/src/Helper/FormHelper.php'
t = builder.read_text()
h = helper.read_text()

def once(old,new,label):
    global t
    if old not in t:
        raise RuntimeError(f'{label} pattern not found')
    t=t.replace(old,new,1)

def rsub(pattern,repl,label,flags=re.S):
    global t
    t2,n=re.subn(pattern,repl,t,count=1,flags=flags)
    if n!=1:
        raise RuntimeError(f'{label} regex replacements={n}')
    t=t2

