payment_line="            ['key'=>'payment','type'=>'payment','category'=>'payment','label'=>Text::_('COM_DECAROFORMS_PAYMENT'),'placeholder'=>'','required'=>false,'config'=>['method'=>'bank','iban'=>'','holder'=>'','amount'=>'','cause'=>'{last_name} {first_name} - {riferimento}']],\n"
