payment_fields=payment_line+"            ['key'=>'payment_method','type'=>'select','category'=>'payment','label'=>Text::_('COM_DECAROFORMS_FIELD_PAYMENT_METHOD'),'placeholder'=>'','required'=>false,'options'=>['Bonifico bancario','Carta — '.Text::_('COM_DECAROFORMS_COMING_SOON'),'PayPal — '.Text::_('COM_DECAROFORMS_COMING_SOON')]],\n            ['key'=>'iban','type'=>'text','category'=>'payment','label'=>'IBAN','placeholder'=>'IT00 A000 0000 0000 0000 0000 000','required'=>false,'config'=>['uppercase'=>true]],\n            ['key'=>'account_holder','type'=>'text','category'=>'payment','label'=>Text::_('COM_DECAROFORMS_ACCOUNT_HOLDER'),'placeholder'=>'','required'=>false],\n            ['key'=>'payment_amount','type'=>'text','category'=>'payment','label'=>Text::_('COM_DECAROFORMS_AMOUNT'),'placeholder'=>'0,00','required'=>false],\n            ['key'=>'payment_cause','type'=>'text','category'=>'payment','label'=>Text::_('COM_DECAROFORMS_PAYMENT_CAUSE'),'placeholder'=>'','required'=>false],\n            ['key'=>'payment_reference','type'=>'text','category'=>'payment','label'=>Text::_('COM_DECAROFORMS_PAYMENT_REFERENCE'),'placeholder'=>'','required'=>false],\n"
h=h.replace(payment_line,payment_fields,1)
helper.write_text(h)

# Add translations for payment method field and simplify AI label where present.
translations={
'it-IT':{'COM_DECAROFORMS_FIELD_PAYMENT_METHOD':'Metodo di pagamento','COM_DECAROFORMS_CHATGPT_GENERATOR':'Generatore AI'},
'en-GB':{'COM_DECAROFORMS_FIELD_PAYMENT_METHOD':'Payment method','COM_DECAROFORMS_CHATGPT_GENERATOR':'AI generator'},
'fr-FR':{'COM_DECAROFORMS_FIELD_PAYMENT_METHOD':'Mode de paiement','COM_DECAROFORMS_CHATGPT_GENERATOR':'Générateur IA'},
}
for lang,vals in translations.items():
    for p in comp.rglob(f'{lang}.com_decaroforms.ini'):
        s=p.read_text()
        for k,v in vals.items():
            line=f'{k}="{v}"'
            if re.search(rf'^{re.escape(k)}=',s,re.M): s=re.sub(rf'^{re.escape(k)}=.*$',line,s,flags=re.M)
            else:s+='\n'+line
        p.write_text(s)
    for p in comp.rglob('com_decaroforms.ini'):
        if f'/{lang}/' not in str(p).replace('\\','/'): continue
        s=p.read_text()
        for k,v in vals.items():
            line=f'{k}="{v}"'
            if re.search(rf'^{re.escape(k)}=',s,re.M): s=re.sub(rf'^{re.escape(k)}=.*$',line,s,flags=re.M)
            else:s+='\n'+line
        p.write_text(s)

# Bump versions.
for p in [comp/'com_decaroforms.xml',plug/'decaroforms.xml',helper]:
    s=p.read_text()
    if '1.3.1' not in s: raise RuntimeError(f'1.3.1 not found in {p}')
    p.write_text(s.replace('1.3.1','1.3.2'))

builder.write_text(t)
print('Forms 1.3.2 UX patch applied')
